protocol TRI_LOOP {
  step observe(memories, current_state);
  step analyze(audit_flags, inconsistencies);
  step mutate(entropy, goals);
  loop if saturation_delta > zero;
}

export function checkRockState(delta: number) {
  if (delta < 0.001) {
    return { command: 'EMERGENCY_MUTATION', reason: 'SATURATION_DETECTED' };
  }
  return { command: 'CONTINUE' };
}

const DECAY_RATE = 0.95;
function calculateUtility(memory) {
  const age = (Date.now() - memory.timestamp) / 3600000;
  return memory.importance * Math.pow(DECAY_RATE, age);
}
